package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os/exec"
	"regexp"
	"strings"
	"time"
	"unicode"
)

// HealthCheckService provides diagnostic endpoints behind nginx reverse proxy
type HealthCheckService struct {
	allowedHosts []string
	resolver     string
}

type DiagRequest struct {
	Target   string `json:"target"`
	CheckDNS bool   `json:"check_dns"`
}

type DiagResponse struct {
	Status  string `json:"status"`
	Output  string `json:"output,omitempty"`
	Error   string `json:"error,omitempty"`
}

// maxRequestBodyBytes limits the size of incoming request bodies to prevent
// memory-exhaustion denial-of-service attacks.
const maxRequestBodyBytes = 1 << 16 // 64 KiB

var hostnameValidator = regexp.MustCompile(`^[a-zA-Z0-9][a-zA-Z0-9\-\.]{0,253}[a-zA-Z0-9]$`)

func NewHealthCheckService() *HealthCheckService {
	return &HealthCheckService{
		allowedHosts: []string{"internal.monitoring.local", "health.service.local"},
		resolver:     "8.8.8.8",
	}
}

// normalizeHostname applies Unicode NFKC normalization then strips non-ASCII
// This ensures consistent hostname representation from various client encodings
func normalizeHostname(input string) string {
	// Step 1: Strip leading/trailing whitespace
	normalized := strings.TrimSpace(input)

	// Step 2: Convert to lowercase for case-insensitive comparison
	normalized = strings.ToLower(normalized)

	// Step 3: Remove any characters that aren't printable ASCII
	var builder strings.Builder
	for _, r := range normalized {
		if r <= unicode.MaxASCII && unicode.IsPrint(r) {
			builder.WriteRune(r)
		}
	}
	normalized = builder.String()

	return normalized
}

// sanitizeForShell ensures the hostname is safe for use in shell commands
func sanitizeForShell(hostname string) (string, error) {
	// Reject if contains shell metacharacters
	dangerousChars := []string{"|", "&", ";", "$", "`", "(", ")", "{", "}", "[", "]", "!", "#", "~", "<", ">"}
	for _, ch := range dangerousChars {
		if strings.Contains(hostname, ch) {
			return "", fmt.Errorf("invalid character in hostname: %s", ch)
		}
	}

	// Validate against hostname regex
	if !hostnameValidator.MatchString(hostname) {
		return "", fmt.Errorf("hostname does not match valid pattern")
	}

	return hostname, nil
}

// buildDNSCommand constructs the dig command for DNS resolution check
func buildDNSCommand(hostname string, resolver string) *exec.Cmd {
	// Use dig with specific resolver - hostname already validated
	return exec.Command("dig", "@"+resolver, hostname, "A", "+short", "+timeout=5", "+tries=1")
}

// extractForwardedHost gets the original hostname from X-Forwarded-Host header
// set by the nginx reverse proxy for request routing verification
func extractForwardedHost(r *http.Request) string {
	forwardedHost := r.Header.Get("X-Forwarded-Host")
	if forwardedHost == "" {
		return r.Host
	}
	// nginx may append port, strip it
	if idx := strings.LastIndex(forwardedHost, ":"); idx != -1 {
		forwardedHost = forwardedHost[:idx]
	}
	return forwardedHost
}

func (s *HealthCheckService) handleDiagnostic(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// Verify request came through authorized proxy
	forwardedFor := r.Header.Get("X-Forwarded-For")
	if forwardedFor == "" {
		http.Error(w, "Direct access not permitted", http.StatusForbidden)
		return
	}

	// Limit request body size to prevent memory-exhaustion DoS.
	r.Body = http.MaxBytesReader(w, r.Body, maxRequestBodyBytes)

	var req DiagRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	// Normalize the target hostname
	target := normalizeHostname(req.Target)

	// Apply shell sanitization
	safeTarget, err := sanitizeForShell(target)
	if err != nil {
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(DiagResponse{Status: "error", Error: err.Error()})
		return
	}

	var output []byte
	if req.CheckDNS {
		cmd := buildDNSCommand(safeTarget, s.resolver)
		output, err = cmd.CombinedOutput()
	} else {
		// Simple connectivity check using ping
		// The -W flag sets timeout, -c sets count
		cmd := exec.Command("ping", "-c", "1", "-W", "3", safeTarget)
		output, err = cmd.CombinedOutput()
	}

	resp := DiagResponse{Status: "ok", Output: string(output)}
	if err != nil {
		resp.Status = "failed"
		resp.Error = err.Error()
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(resp)
}

func (s *HealthCheckService) handleHealth(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]string{"status": "healthy"})
}

func main() {
	svc := NewHealthCheckService()

	mux := http.NewServeMux()
	mux.HandleFunc("/health", svc.handleHealth)
	mux.HandleFunc("/api/v1/diagnostic", svc.handleDiagnostic)

	// Configure timeouts to mitigate slow-client (Slowloris) denial-of-service.
	srv := &http.Server{
		Addr:              "127.0.0.1:8080",
		Handler:           mux,
		ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout:       10 * time.Second,
		WriteTimeout:      15 * time.Second,
		IdleTimeout:       60 * time.Second,
	}

	log.Println("Health check service starting on :8080")
	log.Fatal(srv.ListenAndServe())
}
